Each timestep is tagged with the set of lifecycle IDs it belongs to.  A
lifecycle ID is "<regime>_<number>" for active-regime periods and
"no_<group>" for contiguous no-regime intervals.  Two timesteps from
different lifecycle sets are considered independent for the purpose of
analog selection.

# Build (onset, decay, lc_id) tuples for fast membership checks
lc_intervals = [
    (row["onset"], row["decay"], f"{row['regime']}_{row['number']}")
    for _, row in lc_info.iterrows()
]

# Tag contiguous no-regime periods
no_mask   = lc_attr["lifecycle_wr_index"].reindex(wri.index, fill_value=0) == 0
changes   = no_mask != no_mask.shift(1, fill_value=False)
no_groups = changes.cumsum()
no_ids    = no_groups.where(no_mask)  # NaN for regime periods
no_id_map = {ts: f"no_{int(gid)}" for ts, gid in no_ids.items() if not pd.isna(gid)}


def lifecycle_ids(ts: pd.Timestamp) -> frozenset:
    """Return all lifecycle IDs that contain *ts*."""
    ids = {lc_id for onset, decay, lc_id in lc_intervals if onset <= ts < decay}
    if ts in no_id_map:
        ids.add(no_id_map[ts])
    return frozenset(ids)

# Fraction of non-NaN values per variable / country
coverage = pd.DataFrame({
    "solar":     solar_all.notna().mean(),
    "wind_on":   wind_on_all.notna().mean(),
    "wind_off":  wind_off_all.reindex(columns=wind_on_all.columns).notna().mean()
    if hasattr(wind_off_all, "columns") else np.nan,
})

print("Data coverage (fraction non-NaN):")
print(coverage.to_string())

def _abs_max(anom_dict):
    return pd.concat(anom_dict.values()).dropna().abs().quantile(0.97)

solar_lim   = _abs_max(solar_means)
wind_on_lim = _abs_max(wind_on_means)
temp_lim    = _abs_max(temp_means)

CMAPS = {
    "solar":   (_CMAP_CF,   -solar_lim,   solar_lim),
    "wind_on": (_CMAP_CF,   -wind_on_lim, wind_on_lim),
    "temp":    (_CMAP_TEMP, -temp_lim,    temp_lim),
}
CF_VARS  = list(CMAPS.keys())
CF_TITLES = {
    "solar":   "Solar PV CF anomaly",
    "wind_on": "Wind onshore CF anomaly",
    "temp":    "2 m temperature anomaly (°C)",
}

print("Colour scale limits (±):")
for k, (cmap, vmin, vmax) in CMAPS.items():
    print(f"  {k}: ±{vmax:.4f}")

def find_worst_2day(daily: pd.Series) -> tuple[pd.Timestamp, pd.Timestamp]:
    """Return (start, end) dates of the consecutive 2-day window with lowest mean CF."""
    end   = daily.rolling(2, min_periods=2).mean().idxmin()
    start = end - pd.Timedelta(days=1)
    return start, end

events = {
    "Solar PV CF":      (de_solar_h,    solar_clim,    *find_worst_2day(de_solar_d)),
    "Wind onshore CF":  (de_wind_on_h,  wind_on_clim,  *find_worst_2day(de_wind_on_d)),
    "Wind offshore CF": (de_wind_off_h, wind_off_clim, *find_worst_2day(de_wind_off_d)),
}

for label, (_, _, ev_s, ev_e) in events.items():
    print(f"{label:<22}  worst window: {ev_s.date()} – {ev_e.date()}")
